; shapes.asm -- chapter 7: one instruction of each shape
; generated by gen07.py
        INCLUDE "msx.inc"
        OUTPUT "shapes.rom"
        ORG $4000
        CART_HEADER init
VARS    EQU RAM_START + $100    ; the program's variables: the code is in ROM
RESULTS EQU RAM_START          ; what the program found: the debugger reads it here
init:   di
        ld sp, SYS_AREA
t0:
        nop
t1:
        ld a, $55
t2:
        ld hl, $1234
t3:
        ld a, (RAM_START)
t4:
        rlc b
t5:
        neg
t6:
        ld bc, (RAM_START)
t7:
        ld ix, RAM_START
t8:
        ld a, (ix+5)
t9:
        ld (ix+5), $AA
t10:
        set 1, (ix+2)
t11:
stop:   jr stop
        ds $8000 - $, $FF       ; pad the cartridge to 16 KB
        ASSERT $ == $8000
